#pragma once

// Message metadata: passed to the subscriber callback with every delivery. Meta is generated by the
// broker at publish time; its content is identical on the C++ and SV sides (it crosses via DPI).

#include <cstdint>
#include <string>

namespace shuttle {

struct Meta {
  std::string topic;     // the actual full topic published to (still the concrete topic name for
                         // wildcard subscriptions)
  std::string type_tag;  // message type tag (SHUTTLE_REFLECT name / typeid name)
  std::uint64_t seq;  // per-topic monotonically increasing sequence number, assigned by the broker,
                      // consistent across languages
  std::int64_t time_fs;  // simulation time at publish (femtoseconds), from now_fs()
};

// Current simulation time (femtoseconds).
// svdpi backend: provided over DPI by the SV-side shuttle_sv_time_fs() (converted from $realtime);
// systemc backend: converted from sc_time_stamp().
std::int64_t now_fs();

}  // namespace shuttle
